#include "dfre/mission_event_region_person.hpp"
#include "dfre/resources.hpp"
#include <iostream>
using namespace dfre;using U=std::uint32_t;
namespace {
void check(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}template<class F>void fails(F f){bool stopped=false;try{f();}catch(const std::exception&){stopped=true;}check(stopped,"Required region person failure did not stop");}
MissionEventPersonBindings bind(MissionTickState& state,EventTableRecord& action){return mission_event_person_bindings(state,action,0x1300100,[](U)->U{throw MissionTickError("Lookup table is not reached by this case");},[]{return std::uint16_t(0x037f);});}
void basic(){AiActorTables tables;for(U i=0;i<3;++i){AiActorState actor;actor.active=true;actor.person_slot=i;actor.field_70=i==1?1:2;actor.field_72=i==1?2:1;actor.position[0]=10+i*20;actor.position[1]=20+i*20;tables.groups[3].push_back(actor);}std::vector<AiPersonState> people(1280);for(U i=0;i<3;++i)people[i].owner=actor_handle(3,i);MissionTickState state;init_mission_tick(state,{},std::move(tables),{},std::move(people),1);EventTableRecord action{0,12,2,0,1,100,0,100};auto b=bind(state,action);bool saw_unaligned=false;auto original=b.read;b.read=[&](U at,U width){if(at==0x7cca80+0x6e){check(width==4,"Classification access width");saw_unaligned=true;}return original(at,width);};mission_event_region_person(b,0x1300100);check(saw_unaligned&&(state.people[0].flags24&2)&&!(state.people[1].flags24&2)&&(state.people[2].flags24&2),"WORD70 classification/physical person write");
 for(U i=0;i<3;++i)state.people[i].flags24=0;action[1]=13;mission_event_region_person(b,0x1300100);check(!(state.people[0].flags24&2)&&(state.people[1].flags24&2)&&!(state.people[2].flags24&2),"Kind13 classification");
 action[1]=12;action[5]=9;mission_event_region_person(b,0x1300100);check(!state.people[0].flags24,"Source maxX field order");action[5]=100;bool changed=false;auto current=bind(state,action);auto read=current.read;current.read=[&](U at,U width){const U value=read(at,width);if(at==0x7cca80+12&&!changed){changed=true;action[1]=13;action[5]=0;state.tables.groups[3][2].field_70=1;}return value;};mission_event_region_person(current,0x1300100);check(changed&&(state.people[0].flags24&2)&&!(state.people[2].flags24&2),"Captured rectangle/class and current later actor");
 action[1]=12;action[5]=100;state.people[0].flags24=0;auto fault=bind(state,action);const auto write=fault.write;fault.write=[&](U at,U width,U value){write(at,width,value);throw MissionTickError("Required write failure");};fails([&]{mission_event_region_person(fault,0x1300100);});check(state.people[0].flags24&2,"Person write failure prefix");auto missing=bind(state,action);missing.write={};fails([&]{mission_event_region_person(missing,0x1300100);});action[1]=11;unsigned reads=0;MissionEventPersonBindings early;early.read=[&](U at,U width){check(at==0x1300104&&width==4,"Unsupported kind accessed later bytes");++reads;return U(11);};mission_event_region_person(early,0x1300100);check(reads==1,"Unsupported kind read count");early.read=[&](U at,U width){check(width==4,"Subtype gate width");return at==0x1300104?12u:0u;};mission_event_region_person(early,0x1300100);fails([&]{mission_event_region_person({},0x1300100);});
}
void stock(const std::filesystem::path& folder){AssetStore assets(folder);MissionAssetCache cache(assets);const auto definitions=build_runtime_items(cache.items());std::vector<AiItemDefinition> entries;for(const auto& d:definitions)entries.push_back({d.id,d.flags,d.model,d.ai_data,d.move_data,static_cast<std::uint16_t>(d.hp)});const auto mission=decode_mission(assets.read("C05M07.BMS").bytes);AiActorFactory factory(AiItemDefinitionTable(entries),{});AiActorTables tables;for(std::size_t i=0;i<mission.object_groups[3].size();++i)tables.groups[3].push_back(factory.convert(mission.object_groups[3][i],actor_handle(3,i)));MissionTickState state;init_mission_tick(state,{},std::move(tables),AiItemDefinitionTable(entries),factory.people().slots(),1);U classification=0;for(const auto& actor:state.tables.groups[3])if(actor.person_slot&&(actor.field_70==1||actor.field_70==2)){classification=actor.field_70;break;}check(classification!=0,"Actual group3 person class");EventTableRecord action{0,classification==2?12u:13u,2,0x80000000u,1,0x7fffffffu,0x80000000u,0x7fffffffu};std::vector<U> expected;for(const auto& p:state.people)expected.push_back(p.flags24);unsigned selected=0;for(const auto& actor:state.tables.groups[3])if(actor.field_70==classification&&actor.person_slot){expected.at(*actor.person_slot)|=2;++selected;}check(selected>0,"Actual selected people");auto b=bind(state,action);mission_event_region_person(b,0x1300100);for(std::size_t i=0;i<state.people.size();++i)check(state.people[i].flags24==expected[i],"Actual converted group3/person owner edit");std::cout<<"Actual C05M07 conversion: "<<selected<<" physical group3/person edits passed\n";
}
}
int main(int argc,char** argv){try{basic();if(argc==2)stock(argv[1]);else check(argc==1,"Usage: native_mission_event_region_person [game-folder]");std::cout<<"Event region person checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
